import { useCallback, useState } from 'react';
import { JxChip, JxTagInput } from '@jinx-ui/react';

type ArticleTagPickerProps = {
  label?: string;
  placeholder?: string;
  defaultValue?: string[];
  onChange?: (tags: string[]) => void;
};

function normalize(tags: string[]): string[] {
  const seen = new Set<string>();
  const result: string[] = [];
  for (const raw of tags) {
    const tag = raw.trim();
    const key = tag.toLowerCase();
    if (tag.length === 0 || seen.has(key)) continue;
    seen.add(key);
    result.push(tag);
  }
  return result;
}

export default function ArticleTagPicker({
  label = 'Теги статьи',
  placeholder = 'Введите тег и нажмите Enter',
  defaultValue = [],
  onChange,
}: ArticleTagPickerProps) {
  const [tags, setTags] = useState<string[]>(() => normalize(defaultValue));

  const commit = useCallback(
    (next: string[]) => {
      const cleaned = normalize(next);
      setTags(cleaned);
      onChange?.(cleaned);
    },
    [onChange],
  );

  const removeTag = useCallback(
    (tag: string) => {
      commit(tags.filter((item) => item !== tag));
    },
    [commit, tags],
  );

  return (
    <div style={{ display: 'flex', flexDirection: 'column', gap: '8px' }}>
      <span style={{ color: 'var(--jx-text)', fontWeight: 600 }}>{label}</span>

      <JxTagInput
        ariaLabel={label}
        placeholder={placeholder}
        value={tags}
        onValueChange={commit}
      />

      {tags.length === 0 ? (
        <p style={{ margin: 0, color: 'var(--jx-text-2)' }}>
          Пока ни одного тега. Наберите слово и нажмите Enter, чтобы добавить.
        </p>
      ) : (
        <div
          role="list"
          aria-label={`Выбранные теги: ${tags.length}`}
          style={{ display: 'flex', flexWrap: 'wrap', gap: '8px' }}
        >
          {tags.map((tag) => (
            <JxChip
              key={tag.toLowerCase()}
              role="listitem"
              active
              removable
              onRemove={() => removeTag(tag)}
            >
              {tag}
            </JxChip>
          ))}
        </div>
      )}
    </div>
  );
}

